grammar:{title:"Presente perfecto de subjuntivo (haya + participio)",explain:"Haya, hayas, haya, hayamos, hayan + participio: subjunctive for completed actions. Same triggers as always, but the action already happened: «Me alegra que hayas venido», «Dudo que haya llegado». Use it when a present trigger looks back at a past event.",examples:[
{es:"Espero que el jarabe te haya servido.",en:"I hope the syrup helped you."},
{es:"No creo que hayan abierto la farmacia todavía.",en:"I don't think they've opened the pharmacy yet."},
{es:"Qué bueno que te hayas sentido mejor.",en:"Good thing you've been feeling better."}],
exercises:[
{q:"Me alegra que ___ (recuperarse, tú) tan rápido.",options:["te recuperaste","te hayas recuperado","te recuperes ayer","te habías recuperado"],a:1,hint:"Present emotion + completed action → haya + participio."},
{q:"Dudo que el doctor ya ___ (llegar).",options:["haya llegado","llegó","ha llegado","llegara"],a:0,hint:"Doubt now about a completed event."},
{q:"Es posible que se me ___ (olvidar) las pastillas.",options:["hayan olvidado","haya olvidado","olvidaron","olvidaran"],a:0,hint:"'Las pastillas' plural + se accidental → hayan."},
{q:"No creo que ___ (ser) nada grave.",options:["haya sido","fue","era","es"],a:0,hint:"Completed event judged now → haya sido."}]},
