grammar:{title:"Aunque: ¿indicativo o subjuntivo?",explain:"Aunque + indicativo states a known fact: «Aunque está lloviendo, voy» (even though — it IS raining). Aunque + subjuntivo means 'even if' (unknown/irrelevant): «Aunque llueva, voy.» Past: «aunque llovía» (fact) vs «aunque lloviera» (hypothetical). The mood tells your listener whether you're conceding a fact or dismissing a possibility.",examples:[
{es:"Aunque el pastel es caro, lo voy a comprar.",en:"Even though the cake is expensive, I'm buying it."},
{es:"Aunque sea caro, lo voy a comprar.",en:"Even if it's expensive, I'm buying it."},
{es:"Aunque tuviera dinero, no pagaría eso.",en:"Even if I had money, I wouldn't pay that."}],
exercises:[
{q:"Aunque ___ (estar) a dieta, me comí una concha. (fact)",options:["estoy","esté","estuviera","estaría"],a:0,hint:"Known fact → indicativo."},
{q:"Aunque no ___ (haber) conchas, algo encontraremos. (maybe)",options:["hay","haya","habría","hubo"],a:1,hint:"Unknown possibility → subjuntivo."},
{q:"Aunque me lo ___ (regalar), no lo comería.",options:["regalan","regalaran","regalarían","regalaron"],a:1,hint:"Hypothetical → imperfecto de subj."},
{q:"Iré por pan aunque ___ (llover).",options:["llueve seguro","llueva","llovería","lloviera ayer"],a:1,hint:"'Even if it rains' → subjuntivo."}]},
