grammar:{title:"Haber impersonal: hay, había, hubo, habrá",explain:"Existential haber is ALWAYS singular: «Hay tormentas», «Había árboles caídos», «Hubo daños», «Habrá lluvias», «Va a haber viento», «Puede haber granizo». Never 'habían tormentas' (common error!). Hubo reports events; había describes scenes.",examples:[
{es:"Hubo tres huracanes esa temporada.",en:"There were three hurricanes that season."},
{es:"Había agua hasta las rodillas en el centro.",en:"There was knee-deep water downtown."},
{es:"Va a haber vientos fuertes; asegura las macetas.",en:"There will be strong winds; secure the pots."}],
exercises:[
{q:"___ muchos daños tras el huracán. (event)",options:["Hubieron","Hubo","Habían","Han"],a:1,hint:"Existential haber: always singular → hubo."},
{q:"___ nubes negras hacia la costa. (scene)",options:["Habían","Había","Hubieron","Han"],a:1,hint:"Description → había, singular."},
{q:"Mañana ___ lluvias intensas.",options:["habrán","habrá","van a haber unas","hay de"],a:1,hint:"Future existential → habrá (singular)."},
{q:"Puede ___ granizo por la tarde.",options:["haber","habrá","hay","haya"],a:0,hint:"Poder + infinitive → puede haber."}]},
