grammar:{title:"Estar por vs. estar para",explain:"Estar por + infinitivo = about to (or inclined to): «Está por llover», «Estoy por cancelar». Estar para = ready for / in the mood for: «No estoy para bromas», «La comida está para servirse». Compare: «El sol está por salir» (about to rise) vs «Estamos para ayudarte» (here to help you).",examples:[
{es:"El ferry está por salir; ¡córrele!",en:"The ferry is about to leave; run!"},
{es:"Después de ese sol, no estoy para caminatas.",en:"After that sun, I'm not up for walks."},
{es:"La marea está por cambiar.",en:"The tide is about to change."}],
exercises:[
{q:"El sol ___ ponerse; saca la foto.",options:["está para","está por","es por","es para"],a:1,hint:"About to happen → estar por."},
{q:"Hoy no estoy ___ fiestas; me quemé entero.",options:["por","para","de","a"],a:1,hint:"Not in the mood for → estar para."},
{q:"Estábamos ___ irnos cuando salió el sol.",options:["para que","por","de","en"],a:1,hint:"About to leave → estar por + inf."},
{q:"El restaurante está ___ servirle, señor.",options:["por","para","con","entre"],a:1,hint:"Ready/at your service → para."}]},
