grammar:{title:"Al + infinitivo",explain:"Al + infinitive = 'upon/when doing': «Al llegar, armamos el campamento» (when we arrived). It's compact and very common: «Al ver la lluvia, nos metimos.» With subject stated after: «Al salir el sol, se fue el frío.» For cause, use por + infinitive: «Por no traer repelente, sufrimos.»",examples:[
{es:"Al encender la fogata, llegaron todos.",en:"When the fire got lit, everyone came over."},
{es:"Al amanecer, el lago parecía un espejo.",en:"At dawn, the lake looked like a mirror."},
{es:"Por no revisar el clima, nos empapamos.",en:"For not checking the weather, we got soaked."}],
exercises:[
{q:"___ llegar al campamento, armamos todo.",options:["Al","El","De","En"],a:0,hint:"Upon arriving → al + infinitive."},
{q:"Al ___ el sol, empezó el calor.",options:["salir","salió","saliendo","salga"],a:0,hint:"Al + infinitive, subject after."},
{q:"«Because of not bringing matches»: ___ no traer cerillos.",options:["Al","Por","Para","De"],a:1,hint:"Cause → por + infinitive."},
{q:"___ escuchar el trueno, corrimos a la tienda.",options:["Al","Por","Para","Con"],a:0,hint:"Upon hearing → al."}]},
