grammar:{title:"Pronombres tras preposición: mí, ti, conmigo",explain:"After prepositions use mí, ti, él, ella, usted, nosotros, ustedes: «para mí», «sin ti», «de ella». Con has special forms: conmigo, contigo, consigo. Exceptions — entre, según, hasta, incluso take subject pronouns: «entre tú y yo», «según tú». «A mí me cobró más» adds emphasis.",examples:[
{es:"El plomero trabajó conmigo toda la tarde.",en:"The plumber worked with me all afternoon."},
{es:"Entre tú y yo, cobra carísimo.",en:"Between you and me, he charges a fortune."},
{es:"A mí me hizo descuento; a ti no sé.",en:"He gave me a discount; you, I don't know."}],
exercises:[
{q:"Este presupuesto es para ___ . (me)",options:["yo","mí","me","mi"],a:1,hint:"After preposition → mí (with accent)."},
{q:"¿Vienes ___ a la refaccionaria? (with me)",options:["con mí","conmigo","con yo","consigo"],a:1,hint:"Con + mí → conmigo."},
{q:"Entre ___ y yo, mejor busca otro albañil.",options:["ti","tú","te","tigo"],a:1,hint:"Entre takes subject pronoun: tú."},
{q:"Según ___ , el trabajo queda mañana.",options:["él","el sí","le","se"],a:0,hint:"Según + él (subject form)."}]},
