grammar:{title:"El estilo indirecto periodístico",explain:"News compresses quotes: «Aseguró que investigarían», «Negó haber recibido dinero» (deny + perfect infinitive avoids a clause), «Tras ser cuestionado, afirmó que...». Learn: asegurar, afirmar, señalar, negar, reconocer, advertir + que. Haber + participio after verbs = elegant compression: «Admitió haber mentido.»",examples:[
{es:"El vocero aseguró que habría respuestas pronto.",en:"The spokesman assured there would be answers soon."},
{es:"Negó haber autorizado el contrato.",en:"He denied having authorized the contract."},
{es:"Reconoció no tener todas las cifras.",en:"She admitted not having all the figures."}],
exercises:[
{q:"«'Investigaremos' → Prometió que ___ .»",options:["investigarán","investigarían","investiguen","investigaran"],a:1,hint:"Future → conditional in reported past."},
{q:"«Denied having signed»: Negó ___ .",options:["haber firmado","que firmó él","habiendo firmado","de firmar"],a:0,hint:"Negar + haber + participio."},
{q:"«Admitted lying»: Reconoció ___ .",options:["haber mentido","que mentir","mintiendo","a mentir"],a:0,hint:"Reconocer + perfect infinitive."},
{q:"Verbo NO típico de citas periodísticas:",options:["aseguró","señaló","chismeó","advirtió"],a:2,hint:"Chismear is gossip, not journalism (usually)."}]},
