grammar:{title:"Números en acción: concordancia y lectura",explain:"Uno shortens: veintiún tacos, but veintiuna tortas (feminine!). Cien vs ciento: cien pesos, ciento veinte. Millones need de: dos millones DE personas. Decimals use coma or punto (MX: punto, like US). Percentages take el/un: «el 20 por ciento». «Entre» divides: «120 entre 4 son 30.»",examples:[
{es:"Veintiún años y veintiuna semanas.",en:"Twenty-one years and twenty-one weeks (gender!)."},
{es:"Ciento cincuenta pesos, no cien cincuenta.",en:"150: ciento cincuenta, never 'cien cincuenta'."},
{es:"Tres millones de mexicanos viven fuera.",en:"Three million Mexicans live abroad — with de."}],
exercises:[
{q:"'21 tortas' =",options:["veintiún tortas","veintiuna tortas","veintiuno tortas","veinte y un tortas"],a:1,hint:"Feminine: veintiuna."},
{q:"'150' =",options:["cien cincuenta","ciento cincuenta","cientos cincuenta","cien y cincuenta"],a:1,hint:"Ciento before more digits."},
{q:"'2 million people' =",options:["dos millones personas","dos millones de personas","dos millón de gente","dos de millones"],a:1,hint:"Millones + de + noun."},
{q:"'120 ÷ 4' se dice:",options:["120 entre 4","120 sobre 4","120 por 4","120 menos 4"],a:0,hint:"División → entre."}]},
